<?php
 namespace Pterodactyl\Http\Controllers\Auth; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Log; use Pterodactyl\Facades\Activity; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Models\User; class StarkSsoController extends Controller { private const TOKEN_PATTERN = '/^[a-f0-9]{64}$/'; private const REDIRECT_PATTERN = '#^/[A-Za-z0-9._~/-]*$#'; public function __invoke(Request $request): RedirectResponse { if (! config('stark.sso.enabled')) { return $this->reject($request, 'Single sign-on is not enabled on this panel.'); } $token = $request->query('token'); if (! is_string($token) || ! preg_match(self::TOKEN_PATTERN, $token)) { return $this->reject($request, 'That sign-in link is not valid.'); } $exchangeUrl = (string) config('stark.sso.exchange_url'); $secret = (string) config('stark.sso.secret'); if ($exchangeUrl === '' || $secret === '' || ! preg_match('#^https?://#i', $exchangeUrl)) { Log::error('Stark SSO is enabled but exchange_url/secret are not configured.'); return $this->reject($request, 'Single sign-on is not configured correctly.'); } try { $response = Http::asJson() ->acceptJson() ->withToken($secret) ->withOptions(['verify' => (bool) config('stark.sso.verify_tls', true)]) ->timeout((int) config('stark.sso.timeout', 10)) ->post($exchangeUrl, ['token' => $token]); } catch (\Throwable $e) { Log::error('Stark SSO exchange could not be reached', ['error' => $e->getMessage()]); return $this->reject($request, 'Could not reach the billing panel. Please sign in normally.'); } if (! $response->successful() || $response->json('success') !== true) { Log::warning('Stark SSO exchange refused a token', [ 'status' => $response->status(), 'ip' => $request->ip(), ]); return $this->reject($request, 'That sign-in link has expired or has already been used.'); } $userId = $response->json('pterodactyl_id'); if (! is_int($userId) && ! ctype_digit((string) $userId)) { return $this->reject($request, 'That sign-in link is not valid.'); } $user = User::query()->find((int) $userId); if (! $user) { Log::warning('Stark SSO resolved an account that no longer exists', ['pterodactyl_id' => $userId]); return $this->reject($request, 'That account no longer exists on this panel.'); } if ($user->use_totp) { return $this->reject($request, 'This account has two-factor authentication enabled, so please sign in normally.'); } Auth::guard()->logout(); $request->session()->invalidate(); $request->session()->regenerateToken(); Auth::guard()->login($user, false); $request->session()->regenerate(); try { Activity::event('auth:sso')->withRequestMetadata()->subject($user)->log('signed in from the billing panel'); } catch (\Throwable $e) { Log::warning('Stark SSO could not write an activity entry: '.$e->getMessage()); } Log::info('Stark SSO sign-in completed', ['user_id' => $user->id, 'ip' => $request->ip()]); return redirect($this->safeRedirect($response->json('redirect_path'))); } private function safeRedirect(mixed $path): string { if (! is_string($path) || $path === '' || str_starts_with($path, '//') || str_contains($path, '..')) { return '/'; } return preg_match(self::REDIRECT_PATTERN, $path) ? $path : '/'; } private function reject(Request $request, string $message): RedirectResponse { return redirect()->route('auth.login')->withErrors(['sso' => $message]); } } 